    /// <summary>Il riquadro di disegno dell'icona: 32×32 per Carbon, 256×256 per i loghi Phosphor.</summary>
    public static string ViewBox(string name) => Phosphor.ContainsKey(name) ? PhosphorBox : CarbonBox;

    /// <summary>Il contenuto da mettere dentro lo &lt;svg&gt; (vuoto se il nome non esiste).</summary>
    public static string Body(string name) =>
        Carbon.TryGetValue(name, out var c) ? c
        : Phosphor.TryGetValue(name, out var d) ? $"<path d='{d}'/>"
        : "";
